import mongoose from "mongoose";

// One AI interview attempt by a single user. Created on /start, updated on each
// /answer, and finalized (status completed + scorecard) on /results.
const questionSchema = new mongoose.Schema(
  {
    questionId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "InterviewQuestions",
    },
    questionText: {
      type: String,
      required: true,
    },
    // Short topic tag for the question (e.g. "react-hooks", "system-design").
    // Set when questions are generated by GPT; drives weakness tracking.
    topic: {
      type: String,
      default: "",
    },
    // Difficulty of the generated question ("easy" | "medium" | "hard").
    difficulty: {
      type: String,
      default: "",
    },
    // The transcribed speech (or typed text) of the candidate's answer.
    userAnswer: {
      type: String,
      default: "",
    },
    aiFeedback: {
      type: String,
      default: "",
    },
    score: {
      type: Number,
      min: 0,
      max: 10,
      default: 0,
    },
    timeSpent: {
      type: Number, // seconds
      default: 0,
    },
    followUpAsked: {
      type: Boolean,
      default: false,
    },
    followUpAnswer: {
      type: String,
      default: "",
    },
  },
  { _id: false },
);

const aiInterviewSessionSchema = new mongoose.Schema(
  {
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },
    // Snapshot of the parsed CV summary used to personalize this interview.
    cvAnalysis: {
      type: Object,
      default: {},
    },
    language: {
      type: String,
      enum: ["en", "ar"],
      default: "en",
    },
    questions: {
      type: [questionSchema],
      default: [],
    },
    status: {
      type: String,
      enum: ["in-progress", "completed"],
      default: "in-progress",
    },
    overallScore: {
      type: Number,
      default: 0,
    },
    overallFeedback: {
      type: String,
      default: "",
    },
    strengths: {
      type: [String],
      default: [],
    },
    weaknesses: {
      type: [String],
      default: [],
    },
  },
  { timestamps: true },
);

// History queries list a user's sessions newest-first.
aiInterviewSessionSchema.index({ userId: 1, createdAt: -1 });

const AIInterviewSession = mongoose.model(
  "AIInterviewSession",
  aiInterviewSessionSchema,
);

export default AIInterviewSession;
